target.css:
:root {
  --color-bg: #d4a853;
  --color-border: #7a4e1a;
  --color-header-bg: #7a4e1a;
  --color-header-text: #f5e8c8;
  --color-subtitle: #e8c97a;
  --color-body-bg: #f5e8c8;
  --color-label: #9a6b30;
  --color-value: #3b1f08;
  --color-divider: #c4a060;
  --color-footer-bg: #e8c97a;
  --color-footer-text: #7a4e1a;
  --color-year: #e8c97a;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.kite-tag {
  background-color: var(--color-bg);
  border: 3px solid var(--color-border);
  border-radius: 6px;
  width: 280px;
  overflow: hidden;
}

.tag-header {
  background-color: var(--color-header-bg);
  padding: 12px 16px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  border-bottom: 2px solid var(--color-border);
}

.tag-year {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--color-year);
}

.tag-title {
  font-size: 22px;
  font-weight: 900;
  letter-spacing: 4px;
  color: var(--color-header-text);
  margin: 0;
}

.tag-subtitle {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 1px;
  color: var(--color-subtitle);
}

.tag-body {
  background-color: var(--color-body-bg);
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.entry-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px dashed var(--color-divider);
  padding-bottom: 6px;
}

.entry-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--color-label);
}

.entry-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--color-value);
}

.tag-footer {
  background-color: var(--color-footer-bg);
  padding: 8px 16px;
  text-align: center;
  border-top: 2px solid var(--color-border);
}

.footer-wind {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--color-footer-text);
}

